export type AuditExport = {
  /**
   * 建议的文件名（含本地时间戳）
   */
  filename: string;
  /**
   * CSV 文本（已带 UTF-8 BOM 与表头，行尾 CRLF）
   */
  content: string;
  /**
   * 实际导出的数据行数（不含表头）
   */
  rows: number;
  /**
   * 当前筛选条件下的总条数（可能大于 rows）
   */
  total: number;
  /**
   * 是否因达到导出上限被截断（true 时界面要提示先缩小筛选范围）
   */
  truncated: boolean;
};

export type AuditQuery = {
  /**
   * 页码，从 1 开始
   */
  page?: number;
  /**
   * 每页条数（1~100）
   */
  size?: number;
  /**
   * 关键字：模糊匹配操作人账号名 / 动作（如 password）/ 目标 id / 请求路径
   */
  keyword?: string;
  /**
   * 排序字段（取值见各接口说明，未登记的值会退回默认排序）
   */
  sort?: string;
  /**
   * 排序方向：asc 升序 / desc 降序
   */
  order?: "asc" | "desc";
  /**
   * 只看某个操作人的日志（管理员 id）
   */
  actorId?: string;
  /**
   * 只看某个动作（operationId，取值见 /admin/audit-logs/actions）
   */
  action?: string;
  /**
   * 目标类型筛选
   */
  targetType?: "account" | "role" | "admin" | "announcement" | "mail" | "title" | "soul" | "rank" | "equipment" | "drug" | "item" | "monster" | "npc" | "mall" | "fashion" | "dropTable" | "monsterDrop" | "roleLevel" | "equipmentVariant" | "growthScalar" | "skill" | "status" | "zone" | "guild" | "quest" | "achievement" | "equipAlign" | "equipInAlign" | "map" | "uiEffect" | "audioSetting" | "runtimeParams" | "combatWeights" | "guideSteps" | "equipmentAppearance";
  /**
   * 只看针对某个目标的日志（目标 id）
   */
  targetId?: string;
  /**
   * 只看某个来源 IP（**精确匹配**；反向代理下需要 TRUST_PROXY=true 才准）
   */
  ip?: string;
  /**
   * 只看某个操作人角色
   */
  actorRole?: "super_admin" | "admin" | "viewer";
  /**
   * 结果筛选：true 只看成功 / false 只看失败
   */
  success?: "true" | "false";
  /**
   * 起始时间（毫秒时间戳，含）
   */
  from?: number;
  /**
   * 结束时间（毫秒时间戳，含）
   */
  to?: number;
};

