  owner: "role" | "monster";
  /**
   * 技能名
   */
  label: string;
  /**
   * 技能图标资源路径（resources 相对路径，不含扩展名）
   */
  icon: string;
  /**
   * 分类：0 主动 / 1 被动 / 2 状态 / 3 回复（与客户端 SkillType 同值）
   */
  category: "0" | "1" | "2" | "3";
  /**
   * 目标类型：0 区域 / 1 单体 / 2 群体 / 3 自身（与客户端 SkillTargetType 同值）
   */
  targetType: "0" | "1" | "2" | "3";
  /**
   * 施法动作（客户端动画动作键，如 attack_near；空串 = 不播动作）
   */
  action: string;
  /**
   * 技能特效图集路径（空串 = 无特效）
   */
  effect: string;
  /**
   * 特效是否播在自己身上
   */
  effectOnSelf: boolean;
  /**
   * 冷却（秒）
   */
  cooldown: number;
  /**
   * 释放一次消耗的魔法值
   */
  mpCost: number;
  /**
   * 施法距离（0 = 不限距离）
   */
  distance: number;
  /**
   * 学习 / 开启等级
   */
  levelReq: number;
  /**
   * 描述文案
   */
  description: string;
  /**
   * 伤害系数（下标 = 技能等级 - 1；状态型技能可为空数组）
   */
  damageCoefficients: DamageCoefficient[];
  /**
   * 释放成功后给自身挂的状态 id（空串 = 不挂）
   */
  statusId: string;
  /**
   * 释放动作锁时长（毫秒；0 = 跟动画时长走）
   */
  castLockMs: number;
  /**
   * 是否要求有合法目标（自身 / 状态型技能可关）
   */
  requireTarget: boolean;
  /**
   * 是否可被自动战斗 / 挂机释放
   */
